const prompt = ($json.prompt ?? '').toString().trim();
const lastAnswer = ($json.last_answer ?? '').toString().trim();
const turnCount = Number($json.turn_count ?? 0);
const text = (lastAnswer || prompt).trim();

const tooShort = text.length < 20;
const tooVague = /^(help|anything|something|idk|i don't know|dont know|not sure|whatever|you decide)\b/i.test(text);
const hasAction = /(build|create|send|generate|fix|analy[sz]e|summari[sz]e|extract|automate|integrate|sync|classify|draft|plan|refactor|deploy|convert|transform)/i.test(text);
const hasOutputHint = /(json|csv|email|report|dashboard|summary|table|markdown|ticket|message|file|api)/i.test(text);

const ruleClear = !tooShort && !tooVague && hasAction && hasOutputHint;

if (ruleClear) {
  return [{
    json: {
      status: 'clear',
      source: 'rules',
      turn_count: turnCount,
      original_prompt: prompt,
      final_intent: text,
      done: true
    }
  }];
}

return [{
  json: {
    status: 'needs_ai_fallback',
    source: 'rules',
    turn_count: turnCount,
    original_prompt: prompt,
    current_text: text,
    rule_signals: { tooShort, tooVague, hasAction, hasOutputHint },
    done: false
  }
}];

const intent = ($json.final_intent ?? '').toString();

return [{
  json: {
    status: 'ready_for_processing',
    source: $json.source ?? 'unknown',
    intent,
    processing_payload: {
      prompt: intent
    },
    message: 'Intention is clear. Proceeding to next processing node.'
  }
}];

const originalPrompt = ($json.original_prompt ?? '').toString().trim();
const currentText = ($json.current_text ?? '').toString().trim();
const turnCount = Number($json.turn_count ?? 0);

const raw = ($json.output ?? $json.text ?? '').toString().trim();
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      status: 'need_clarification',
      source: 'ai-fallback-parse-error',
      turn_count: turnCount + 1,
      original_prompt: originalPrompt,
      current_text: currentText,
      question: 'Please clarify your exact goal, input source, and desired output format.',
      hint: `AI response was not valid JSON: ${raw.slice(0, 200)}`,
      done: false
    }
  }];
}

if (parsed?.clear_intent === true) {
  return [{
    json: {
      status: 'clear',
      source: 'ai-fallback',
      turn_count: turnCount,
      original_prompt: originalPrompt,
      final_intent: (parsed.refined_intent || currentText || originalPrompt).toString().trim(),
      done: true
    }
  }];
}

return [{
  json: {
    status: 'need_clarification',
    source: 'ai-fallback',
    turn_count: turnCount + 1,
    original_prompt: originalPrompt,
    current_text: currentText,
    question: (parsed?.clarification_question || 'Could you clarify your goal, input source, and expected output?').toString(),
    missing_fields: Array.isArray(parsed?.missing_fields) ? parsed.missing_fields : [],
    done: false
  }
}];
